    "id": 510,
    "topic": "1BP461",
    "question": "A student computes daily returns for a month with prices %>% group_by(symbol, month) %>% mutate(logreturn = log(adjusted) - lag(log(adjusted))) and then sums them. What is the problem?",
    "option_a": "The sum of log returns can never be converted to a simple return",
    "option_b": "lag() cannot be used together with group_by()",
    "option_c": "The grouping by month sorts the days alphabetically",
    "option_d": "The first day of each month gets NA, losing that return",
