    "question": "Which expression gives the global minimum-variance portfolio of risky assets under the budget constraint $\\mathbf w'\\mathbf 1 = 1$ and no other constraints?",
    "option_a": "$w=\\dfrac{\\Sigma\\mathbf 1}{\\mathbf 1'\\Sigma\\mathbf 1}$",
    "option_b": "$w=\\dfrac{\\Sigma^{-1}\\mathbf 1}{\\mathbf 1'\\Sigma^{-1}\\mathbf 1}$",
    "option_c": "$w=\\dfrac{\\Sigma^{-1}\\mu}{\\mathbf 1'\\Sigma^{-1}\\mu}$",
    "option_d": "$w=\\dfrac{\\mathbf 1/\\sigma}{\\mathbf 1'(\\mathbf 1/\\sigma)}$",
    "correct": "B",
    "explanation": "The Lagrangian $\\mathbf w'\\Sigma\\mathbf w+\\lambda(\\mathbf w'\\mathbf 1-1)$ gives $\\mathbf w\\propto\\Sigma^{-1}\\mathbf 1$, normalised so the weights sum to 1. Using $\\Sigma$ instead of $\\Sigma^{-1}$ is wrong, $\\Sigma^{-1}\\mu$ is driven by returns, and $1/\\sigma$ is the naive risk parity heuristic that ignores correlations.",
    "created_at": "2026-11-10 13:58:49",
